/**
 * Build steps: printable, step-by-step instructions for building and installing the design,
 * roughly bottom to top. Generated by the engine from the derived design and the cut report;
 * steps can be checked off (remembered in this browser, per project).
 */
import { buildInstructions, type BuildPart, type BuildPlan, type BuildStep } from '@cabinet-studio/engine';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useFormatter } from '../../lib/units';
import { getProjectResults } from '../../store/derived';
import { useEditor } from '../../store/store';
import { OutputBoundary, Swatch } from '../outputs/common';
import { locateOwner, useCutReport } from '../outputs/state';
import '../outputs/outputs.css';
import './build.css';

/** Portrait pages, only while this view is mounted (other views keep their own orientation). */
const PAGE_CSS = '@page { size: portrait; margin: 0.5in; }';

/** Keeps the app's old name, like the project storage keys (see store/library.ts). */
const progressKey = (projectId: string) => `built-in-planner:build-progress:${projectId}`;

/** Checked-off steps for a project, kept in this browser. */
function useProgress(projectId: string): [Set<string>, (id: string, done: boolean) => void, () => void] {
  const read = useCallback((): Set<string> => {
    try {
      const raw = localStorage.getItem(progressKey(projectId));
      return new Set(raw ? (JSON.parse(raw) as string[]) : []);
    } catch {
      return new Set();
    }
  }, [projectId]);
  const [done, setDone] = useState(read);
  useEffect(() => setDone(read()), [read]);
  const save = (next: Set<string>) => {
    setDone(next);
    try {
      localStorage.setItem(progressKey(projectId), JSON.stringify([...next]));
    } catch {
      // Not remembered (storage unavailable); the checks still work for now.
    }
  };
  const toggle = (id: string, on: boolean) => {
    const next = new Set(done);
    if (on) next.add(id);
    else next.delete(id);
    save(next);
  };
  return [done, toggle, () => save(new Set())];
}

function Build() {
  const { project, report } = useCutReport();
  // The report and results are cached per project snapshot; so is the plan.
  const plan: BuildPlan = useMemo(() => buildInstructions(project, getProjectResults(project), report), [project, report]);
  const [done, toggle, reset] = useProgress(project.id);
  const date = useMemo(() => new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' }), []);
  const doneCount = plan.sections.reduce((n, s) => n + s.steps.filter((st) => done.has(st.id)).length, 0);
  let number = 0;

  return (
    <div className="output-view out build">
      <style>{PAGE_CSS}</style>
      <header className="out-head build-head">
        <div>
          <h1>Build steps</h1>
          <p className="out-sub">
            {project.name} · {plan.stepCount} steps, roughly bottom to top · {date}
          </p>
        </div>
        <div className="out-actions no-print">
          {doneCount > 0 && (
            <>
              <span className="muted">
                {doneCount} of {plan.stepCount} done
              </span>
              <button onClick={reset} title="Clear the checkmarks">
                Clear
              </button>
            </>
          )}
          <button className="primary" onClick={() => window.print()} title="Print the steps (portrait)">
            Print
          </button>
        </div>
      </header>
      <p className="build-intro">
        Parts are named by their cut list letters (Cut list tab). Sizes are finished sizes: length × width × thickness. The box sheets on the Drawings tab show where holes, partitions and
        shelves go. Read each step through before you start it.
      </p>

      <nav className="build-toc" aria-label="Contents">
        <ol>
          {plan.sections.map((s) => (
            <li key={s.id}>
              <a href={`#build-${s.id}`}>{s.title}</a>
              <span className="muted"> · {s.steps.length === 1 ? '1 step' : `${s.steps.length} steps`}</span>
            </li>
          ))}
        </ol>
      </nav>

      {plan.sections.map((s) => (
        <section key={s.id} id={`build-${s.id}`} className="build-section">
          <h2>{s.title}</h2>
          {s.intro && <p className="build-section-intro">{s.intro}</p>}
          {s.steps.map((st) => {
            number++;
            return <Step key={st.id} n={number} step={st} done={done.has(st.id)} onToggle={(on) => toggle(st.id, on)} />;
          })}
        </section>
      ))}
    </div>
  );
}

function Step({ n, step, done, onToggle }: { n: number; step: BuildStep; done: boolean; onToggle: (on: boolean) => void }) {
  const locate = step.locate;
  return (
    <article className={`build-step${done ? ' done' : ''}`}>
      <header>
        <label className="build-check" title={done ? 'Done (click to clear)' : 'Mark as done'}>
          <input type="checkbox" checked={done} onChange={(e) => onToggle(e.target.checked)} />
          <span className="build-num">{n}</span>
        </label>
        <div className="build-title">
          <h3>{step.title}</h3>
          {step.subtitle && <p className="muted">{step.subtitle}</p>}
        </div>
        {locate && (
          <button className="link no-print" onClick={() => locateOwner(locate)} title="Show this in the design">
            Show in design
          </button>
        )}
      </header>
      {step.how.length > 0 && (
        <ol className="build-how">
          {step.how.map((h, i) => (
            <li key={i}>{h}</li>
          ))}
        </ol>
      )}
      {step.items && step.items.length > 0 && (
        <ul className="build-items">
          {step.items.map((item, i) => (
            <li key={i}>{item}</li>
          ))}
        </ul>
      )}
      {step.parts.length > 0 && <PartsTable parts={step.parts} />}
      {step.hardware.length > 0 && (
        <p className="build-hardware">
          <strong>Hardware:</strong> {step.hardware.join('; ')}
        </p>
      )}
      {step.notes.length > 0 && (
        <ul className="build-notes">
          {step.notes.map((note, i) => (
            <li key={i}>{note}</li>
          ))}
        </ul>
      )}
    </article>
  );
}

function PartsTable({ parts }: { parts: readonly BuildPart[] }) {
  const { fmt } = useFormatter();
  const materials = useEditor((s) => s.project.materials);
  const mat = (id: string) => materials.find((m) => m.id === id);
  return (
    <table className="out-table build-parts">
      <thead>
        <tr>
          <th title="Cut list letter">#</th>
          <th className="num">Qty</th>
          <th>Part</th>
          <th className="num">L × W × T</th>
          <th>Material</th>
        </tr>
      </thead>
      <tbody>
        {parts.map((p, i) => (
          <tr key={`${p.label}-${i}`}>
            <td className="build-label">{p.label || '–'}</td>
            <td className="num">{p.qty}</td>
            <td>{p.name}</td>
            <td className="num len">
              {fmt(p.length)} × {fmt(p.width)} × {fmt(p.thickness)}
            </td>
            <td className="build-mat">
              <Swatch color={mat(p.materialId)?.color} />
              {mat(p.materialId)?.name ?? p.materialId}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export function BuildView() {
  return (
    <OutputBoundary>
      <Build />
    </OutputBoundary>
  );
}
